/**
 * GET /api/metrics
 * Pulls telemetry metrics. Falls back to Node OS stats if telemetry collector is not running.
 */
app.get('/api/metrics', (req, res) => {
  if (fs.existsSync(TELEMETRY_PATH)) {
    try {
      const raw = fs.readFileSync(TELEMETRY_PATH, 'utf8');
      const metrics = JSON.parse(raw);
      metrics.collector_active = true;
      return res.json(metrics);
    } catch (err) {
      // JSON parse error, fall through to OS fallback
    }
  }

  // Fallback system metrics if daemon is not running
  const totalMem = os.totalmem();
  const freeMem = os.freemem();
  const usedMem = totalMem - freeMem;
  const memPercent = Math.round((usedMem / totalMem) * 100);
  const cpus = os.cpus();
  const cores = cpus.length;
  
  res.json({
    timestamp: new Date().toISOString(),
    collector_active: false,
    system_grade: "B",
    average_load_percent: 25.0,
    os_platform: process.platform,
    uptime: Math.round(os.uptime()),
    cpu: {
      percent: 20.0,
      cores: cores,
      threads: cores
    },
    memory: {
      total_bytes: totalMem,
      available_bytes: freeMem,
      used_bytes: usedMem,
      percent: memPercent
    },
    disk: {
      total_bytes: 500 * 1024 * 1024 * 1024,
      free_bytes: 250 * 1024 * 1024 * 1024,
      used_bytes: 250 * 1024 * 1024 * 1024,
      percent: 50
    },
    gpu: {
      available: false,
      note: "Telemetry collector daemon is inactive. Launch python telemetry.py to check GPU acceleration."
    }
  });
});

/**
 * GET /api/pm2
 * Resolves list of running processes in PM2 via 'pm2 jlist'
 */
app.get('/api/pm2', async (req, res) => {
  const result = await runCommand('pm2 jlist');
  if (!result.success) {
    return res.json({
      pm2_active: false,
      processes: [],
      error: "PM2 not running or not found in PATH."
    });
  }

  try {
    const list = JSON.parse(result.stdout);
    const processes = list.map(p => ({
      pid: p.pid,
      id: p.pm_id,
      name: p.name,
      status: p.pm2_env.status,
      uptime: Math.round((Date.now() - p.pm2_env.pm_uptime) / 1000),
      restarts: p.pm2_env.restart_time,
      cpu: p.monit ? p.monit.cpu : 0,
      memory: p.monit ? p.monit.memory : 0
    }));
    res.json({
      pm2_active: true,
      processes
    });
  } catch (err) {
    res.json({
      pm2_active: true,
      processes: [],
      error: "Failed to parse PM2 output."
    });
  }
});

/**
 * POST /api/pm2/control
 * Send controls to PM2 processes (start, stop, restart)
 */
app.post('/api/pm2/control', async (req, res) => {
  const { action, id } = req.body;
  if (!action || id === undefined) {
    return res.status(400).json({ error: "Missing action or process id." });
  }

  const allowedActions = ['start', 'stop', 'restart'];
  if (!allowedActions.includes(action)) {
    return res.status(400).json({ error: "Invalid action type." });
  }

  const idStr = String(id).trim();
  if (!/^[a-zA-Z0-9_\-]+$/.test(idStr)) {
     return res.status(400).json({ error: "Invalid process identifier pattern." });
  }

  console.log(`[PM2 Control] Executing 'pm2 ${action} ${idStr}'`);
  const result = await runCommand(`pm2 ${action} ${idStr}`);
  
  if (result.success) {
    res.json({ success: true, message: `Successfully executed '${action}' on process '${idStr}'` });
  } else {
    res.status(500).json({ error: `Command failed: ${result.error}`, details: result.stderr });
  }
});

